import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const VIEW_SCOPES = ['전체', '부서', '개인'];
const USE_YNS = ['사용', '미사용'];
const SYSTEM_TYPES = ['ERP', '그룹웨어'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function idOf(value: unknown, label: string): string {
  const ok =
    (typeof value === 'number' && Number.isInteger(value) && value > 0) ||
    (typeof value === 'string' && value.trim() !== '' && Number.isInteger(Number(value)) && Number(value) > 0);
  if (!ok) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 올바르게 입력해 주세요.');
  }
  return String(value).trim();
}

function enumOf(value: unknown, allowed: string[], label: string): string {
  if (typeof value !== 'string' || !allowed.includes(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return value;
}

function empty(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

@Controller('api/v1')
export class FnSfr00101Controller {
  @Post('/menu-permissions')
  @HttpCode(200)
  async createMenuPermission(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원 ID');
    const menuId = idOf(data['menuId'], '메뉴 ID');
    const permissionRoleId = idOf(data['permissionRoleId'], '사용 권한 구분 ID');
    const viewScope = enumOf(data['viewScope'], VIEW_SCOPES, '조회 범위');
    const useYn = enumOf(data['useYn'], USE_YNS, '사용 여부');
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      const menus = await db.query(
        'SELECT menu_id FROM menu WHERE menu_id = CAST(:menuId AS bigint)',
        { menuId },
      );
      if (menus.length === 0) {
        throw new ApiError(404, 'MENU_NOT_FOUND', '메뉴를 찾을 수 없습니다.');
      }
      const roles = await db.query(
        'SELECT permission_role_id FROM permission_role WHERE permission_role_id = CAST(:permissionRoleId AS bigint)',
        { permissionRoleId },
      );
      if (roles.length === 0) {
        throw new ApiError(404, 'PERMISSION_ROLE_NOT_FOUND', '사용 권한 구분을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT menu_permission_id FROM menu_permission WHERE employee_id = CAST(:employeeId AS bigint) AND menu_id = CAST(:menuId AS bigint)',
        { employeeId, menuId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'MENU_PERMISSION_DUPLICATED', '같은 임직원·메뉴에 이미 권한이 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO menu_permission (employee_id, menu_id, permission_role_id, view_scope, use_yn, created_at, updated_at) ' +
          'VALUES (CAST(:employeeId AS bigint), CAST(:menuId AS bigint), CAST(:permissionRoleId AS bigint), :viewScope, :useYn, now(), now()) ' +
          'RETURNING menu_permission_id AS "menuPermissionId", employee_id AS "employeeId", menu_id AS "menuId", ' +
          'permission_role_id AS "permissionRoleId", view_scope AS "viewScope", use_yn AS "useYn"',
        { employeeId, menuId, permissionRoleId, viewScope, useYn },
      );
      const created = rows[0];
      await db.execute(
        'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
          "VALUES ('menu_permission', CAST(:targetId AS bigint), '등록', now(), CAST(:userId AS bigint), NULL, :after, now(), now())",
        { targetId: String(created.menuPermissionId), userId: user.id, after: JSON.stringify(created) },
      );
      return created;
    });
  }

  @Patch('/menu-permissions/:menuPermissionId')
  async updateMenuPermission(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const menuPermissionId = idOf(req.params['menuPermissionId'], '메뉴 사용 권한 ID');
    const data = checks.inputOf(req.body);
    const permissionRoleId = empty(data['permissionRoleId']) ? null : idOf(data['permissionRoleId'], '사용 권한 구분 ID');
    const viewScope = empty(data['viewScope']) ? null : enumOf(data['viewScope'], VIEW_SCOPES, '조회 범위');
    const useYn = empty(data['useYn']) ? null : enumOf(data['useYn'], USE_YNS, '사용 여부');
    if (permissionRoleId === null && viewScope === null && useYn === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경할 항목을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const selectSql =
        'SELECT menu_permission_id AS "menuPermissionId", employee_id AS "employeeId", menu_id AS "menuId", ' +
        'permission_role_id AS "permissionRoleId", view_scope AS "viewScope", use_yn AS "useYn" ' +
        'FROM menu_permission WHERE menu_permission_id = CAST(:menuPermissionId AS bigint)';
      const befores = await db.query(selectSql, { menuPermissionId });
      if (befores.length === 0) {
        throw new ApiError(404, 'MENU_PERMISSION_NOT_FOUND', '메뉴 사용 권한을 찾을 수 없습니다.');
      }
      const before = befores[0];
      if (permissionRoleId !== null) {
        const roles = await db.query(
          'SELECT permission_role_id FROM permission_role WHERE permission_role_id = CAST(:permissionRoleId AS bigint)',
          { permissionRoleId },
        );
        if (roles.length === 0) {
          throw new ApiError(404, 'PERMISSION_ROLE_NOT_FOUND', '사용 권한 구분을 찾을 수 없습니다.');
        }
        const dup = await db.query(
          'SELECT menu_permission_id FROM menu_permission WHERE employee_id = CAST(:employeeId AS bigint) ' +
            'AND menu_id = CAST(:menuId AS bigint) AND permission_role_id = CAST(:permissionRoleId AS bigint) ' +
            'AND menu_permission_id <> CAST(:menuPermissionId AS bigint)',
          {
            employeeId: String(before.employeeId),
            menuId: String(before.menuId),
            permissionRoleId,
            menuPermissionId,
          },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'MENU_PERMISSION_DUPLICATED', '같은 임직원·메뉴에 이미 권한이 있습니다.');
        }
      }
      await db.execute(
        'UPDATE menu_permission SET ' +
          'permission_role_id = COALESCE(CAST(:permissionRoleId AS bigint), permission_role_id), ' +
          'view_scope = COALESCE(:viewScope, view_scope), ' +
          'use_yn = COALESCE(:useYn, use_yn), ' +
          'updated_at = now() ' +
          'WHERE menu_permission_id = CAST(:menuPermissionId AS bigint)',
        { permissionRoleId, viewScope, useYn, menuPermissionId },
      );
      const afters = await db.query(selectSql, { menuPermissionId });
      const after = afters[0];
      await db.execute(
        'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
          "VALUES ('menu_permission', CAST(:targetId AS bigint), '수정', now(), CAST(:userId AS bigint), :before, :after, now(), now())",
        {
          targetId: menuPermissionId,
          userId: user.id,
          before: JSON.stringify(before),
          after: JSON.stringify(after),
        },
      );
      return {
        menuPermissionId: after.menuPermissionId,
        permissionRoleId: after.permissionRoleId,
        viewScope: after.viewScope,
        useYn: after.useYn,
      };
    });
  }

  @Get('/menu-permissions')
  async listMenuPermissions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const employeeId = empty(query['employeeId']) ? null : idOf(query['employeeId'], '임직원 ID');
    const systemType = empty(query['systemType']) ? null : enumOf(query['systemType'], SYSTEM_TYPES, '적용 시스템 구분');
    let page = 0;
    if (!empty(query['page'])) {
      page = Number(query['page']);
      if (!Number.isInteger(page) || page < 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
      }
    }
    let size = DEFAULT_SIZE;
    if (!empty(query['size'])) {
      size = Number(query['size']);
      if (!Number.isInteger(size) || size < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
      }
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const offset = page * size;
    return transaction(async (db) => {
      const where =
        'FROM menu_permission mp JOIN menu m ON m.menu_id = mp.menu_id ' +
        'WHERE (CAST(:employeeId AS bigint) IS NULL OR mp.employee_id = CAST(:employeeId AS bigint)) ' +
        'AND (CAST(:systemType AS varchar) IS NULL OR m.system_type = CAST(:systemType AS varchar))';
      const counts = await db.query('SELECT COUNT(*) AS "total" ' + where, { employeeId, systemType });
      const items = await db.query(
        'SELECT mp.menu_permission_id AS "menuPermissionId", mp.employee_id AS "employeeId", mp.menu_id AS "menuId", ' +
          'mp.permission_role_id AS "permissionRoleId", mp.view_scope AS "viewScope", mp.use_yn AS "useYn" ' +
          where +
          ' ORDER BY mp.menu_permission_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { employeeId, systemType, size, offset },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }
}

