import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const VIEW_SCOPES: [string, string][] = [['전체', '전체'], ['부서', '부서'], ['개인', '개인']];
const USE_YNS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const SYSTEMS: [string, string][] = [['ERP', 'ERP'], ['그룹웨어', '그룹웨어']];
const SIZE = 20;

export default function FnSfr00101Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [systemType, setSystemType] = useState('');
  const [page, setPage] = useState(0);
  const [applied, setApplied] = useState<{ employeeId: number | string; systemType: string }>({ employeeId: '', systemType: '' });
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () =>
      call<Page>('GET', '/menu-permissions', role, undefined, {
        employeeId: applied.employeeId,
        systemType: applied.systemType,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  const items = data ? data.items : [];
  const usedCount = items.filter((r) => r['useYn'] === '사용').length;
  const unusedCount = items.filter((r) => r['useYn'] === '미사용').length;

  function search() {
    setPage(0);
    setApplied({ employeeId, systemType });
  }

  function reset() {
    setEmployeeId('');
    setSystemType('');
    setPage(0);
    setApplied({ employeeId: '', systemType: '' });
  }

  function openCreate() {
    setForm({ viewScope: '', useYn: '사용' });
    setCreating(true);
  }

  function openEdit(row: Row) {
    setForm({
      permissionRoleId: row['permissionRoleId'],
      viewScope: row['viewScope'],
      useYn: row['useYn'],
    });
    setEditing(row);
  }

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  async function submitCreate() {
    const missing: string[] = [];
    if (!form['employeeId']) missing.push('임직원');
    if (!form['menuId']) missing.push('메뉴');
    if (!form['permissionRoleId']) missing.push('사용 권한 구분');
    if (!form['viewScope']) missing.push('조회 범위');
    if (!form['useYn']) missing.push('사용 여부');
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력해 주세요: ' + missing.join(', '));
    }
    await call('POST', '/menu-permissions', role, {
      employeeId: form['employeeId'],
      menuId: form['menuId'],
      permissionRoleId: form['permissionRoleId'],
      viewScope: form['viewScope'],
      useYn: form['useYn'],
    });
    notify('권한을 부여했습니다.');
    setCreating(false);
    reload();
  }

  async function submitEdit() {
    if (!editing) return;
    if (!form['permissionRoleId'] || !form['viewScope'] || !form['useYn']) {
      throw new Error('사용 권한 구분, 조회 범위, 사용 여부를 모두 입력해 주세요.');
    }
    await call('PATCH', '/menu-permissions/' + String(editing['menuPermissionId']), role, {
      permissionRoleId: form['permissionRoleId'],
      viewScope: form['viewScope'],
      useYn: form['useYn'],
    });
    notify('권한을 변경했습니다.');
    setEditing(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>권한 현황</h2>
        <Tiles
          items={[
            ['조회 건수', data ? data.total.toLocaleString() : '-'],
            ['사용 (현재 쪽)', usedCount],
            ['미사용 (현재 쪽)', unusedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>메뉴 사용 권한</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
          <Field label="적용 시스템 구분">
            <Select value={systemType} onChange={setSystemType} options={SYSTEMS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>권한 부여</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={items}
          empty="등록된 권한이 없습니다."
          onRowClick={openEdit}
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'menuId', label: '메뉴 ID', render: (r) => <RefName table="menu" role={role} value={r['menuId']} /> },
            { key: 'permissionRoleId', label: '사용 권한 구분 ID', render: (r) => <RefName table="permission_role" role={role} value={r['permissionRoleId']} /> },
            { key: 'viewScope', label: '조회 범위', render: (r) => <Badge value={r['viewScope']} /> },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
            { key: 'menuPermissionId', label: '변경', render: (r) => <button type="button" onClick={() => openEdit(r)}>변경</button> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="권한 부여" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="저장">
            <Field label="임직원 ID" required>
              <LookupSelect table="employee" role={role} value={form['employeeId']} onChange={(v) => setField('employeeId', v)} />
            </Field>
            <Field label="메뉴 ID" required hint="ERP 또는 그룹웨어 메뉴">
              <LookupSelect table="menu" role={role} value={form['menuId']} onChange={(v) => setField('menuId', v)} />
            </Field>
            <Field label="사용 권한 구분 ID" required>
              <LookupSelect table="permission_role" role={role} value={form['permissionRoleId']} onChange={(v) => setField('permissionRoleId', v)} />
            </Field>
            <Field label="조회 범위" required>
              <Select value={form['viewScope']} onChange={(v) => setField('viewScope', v)} options={VIEW_SCOPES} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={form['useYn']} onChange={(v) => setField('useYn', v)} options={USE_YNS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {editing ? (
        <Drawer title="권한 변경" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="변경">
            <Field label="임직원 ID">
              <RefName table="employee" role={role} value={editing['employeeId']} />
            </Field>
            <Field label="메뉴 ID">
              <RefName table="menu" role={role} value={editing['menuId']} />
            </Field>
            <Field label="사용 권한 구분 ID" required>
              <LookupSelect table="permission_role" role={role} value={form['permissionRoleId']} onChange={(v) => setField('permissionRoleId', v)} />
            </Field>
            <Field label="조회 범위" required>
              <Select value={form['viewScope']} onChange={(v) => setField('viewScope', v)} options={VIEW_SCOPES} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={form['useYn']} onChange={(v) => setField('useYn', v)} options={USE_YNS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
